import {WORLDS} from '../runner/worlds.js';
export function adventureHost(){try{return parent!==window&&new URLSearchParams(location.search).get('arcade')==='1'?parent.arcadeAdventureHost||null:null;}catch{return null;}}
export function configureHostedWorld(w){const h=adventureHost();if(h){w.hostTheme=h.world;w.stations.forEach((s,i)=>s.name=['boss','final'].includes(s.type)?'Crystal Guardian':'Crystal Discovery '+(i+1));}return w;}
const hex=n=>'#'+n.toString(16).padStart(6,'0');
export function destinationBackdrop(c,world,cam,t){const theme=adventureHost()?.world;if(!theme)return false;const p=WORLDS[theme],g=c.createLinearGradient(0,0,0,720);g.addColorStop(0,hex(p.sky));g.addColorStop(1,hex(p.fog));c.fillStyle=g;c.fillRect(0,0,1200,720);const ball=(x,y,r,color)=>{c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();};for(let i=0;i<12;i++){const x=((i*137-cam*.23)%1400+1400)%1400-90,y=80+i%3*60;c.fillStyle=hex(p.edge);if(theme==='jungle'||theme==='haunted'){c.fillRect(x,260,22,300);ball(x+10,250,80,theme==='jungle'?'#55a87a':'#776594');if(theme==='haunted'){ball(x+40,430+Math.sin(t+i)*10,22,'#b5ede0');ball(x+34,426+Math.sin(t+i)*10,3,'#354c61');}}else if(theme==='castle'){c.fillRect(x,190,85,380);for(let j=0;j<3;j++)c.fillRect(x+j*32,165,20,40);c.fillStyle='#45456d';c.fillRect(x+30,230,25,45);}else if(theme==='underwater'){c.fillRect(x,390,9,150);c.fillRect(x-20,420,45,9);ball(x+35,((t*22+i*71)%440),6,'#a6e9f688');c.fillStyle='#ffd7a5';c.beginPath();c.ellipse(x+70,y+140,20,9,0,0,Math.PI*2);c.fill();}else if(theme==='cosmic'){ball(x,y,25+i%3*12,i%2?'#c6a7e0':'#8bd7de');ball(x+50,y-40,2,'#fff0b8');}else{c.beginPath();c.moveTo(x-110,565);c.lineTo(x+45,100);c.lineTo(x+210,565);c.closePath();c.fill();c.fillStyle=theme==='frozen'?'#f4fdff':'#ff997b';c.beginPath();c.moveTo(x+20,175);c.lineTo(x+45,100);c.lineTo(x+72,175);c.closePath();c.fill();}}return true;}
